#!/usr/bin/env python3
"""Build buyer-only displays and briefs from the approved public catalogue."""
from pathlib import Path
from html import escape
import csv,json,re,shutil,subprocess
from buyer_information import dossier_html,dossier_brief
from pricing_publication import record as price_record,full_html as price_html,brief_prices,usd,pair,usd_number

ROOT=Path(__file__).resolve().parents[1]
HUB='https://thearchitect-max.github.io/MyProjects/'
def money(v):return 'EUR '+format(v,',')
def ul(items):return '<ul>'+''.join('<li>'+escape(s)+'</li>' for s in items)+'</ul>'
def main():
 subprocess.run(['node',str(ROOT/'tools/build_calculation_check.cjs')],check=True)
 d=json.loads((ROOT/'assets/buyer-catalogue.json').read_text());projects=d['projects'];cats={c['id']:c for c in d['categories']}
 dossiers=json.loads((ROOT/'assets/buyer-dossiers.json').read_text());dossier_by_ref={p['ref']:p for p in dossiers['projects']};applications=json.loads((ROOT/'assets/application-combinations.json').read_text())
 pricing=json.loads((ROOT/'assets/pricing-catalogue.json').read_text());assert len(projects)==len(pricing['projects'])==108
 header='<header class="site-header"><a class="wordmark" href="'+HUB+'"><span class="brand-mark" aria-hidden="true">TA</span><span>THEARCHITECT_MAX<span class="wordmark-sub">PRIVATE SOFTWARE IP</span></span></a><nav aria-label="Primary"><a class="hub-return button secondary compact" data-hub-return href="'+HUB+'">← Return to hub</a><a href="'+HUB+'portfolio.html">IP collection</a><a href="'+HUB+'buyers.html">Buyer fit</a><a href="'+HUB+'valuation.html">Prices &amp; sources</a><a href="../../acquisition.html">Acquisition</a></nav><span class="edition">IP ASSET EXHIBITION</span></header>'
 footer='<footer class="site-footer"><div><strong>THEARCHITECT_MAX</strong><p>Independent software assets. Individually scoped acquisition.</p></div><div><a href="'+HUB+'policy.html">Terms &amp; disclosure</a><p>© 2026 · First-party rights reserved.</p></div><a class="button secondary compact" data-hub-return href="'+HUB+'">← Return to hub</a></footer>'
 dialog='<dialog id="enquiry-dialog" aria-labelledby="enquiry-heading"><div class="dialog-head"><h2 id="enquiry-heading">Prepare an acquisition enquiry</h2><button class="icon-button" data-close-dialog aria-label="Close enquiry">×</button></div><p>This draft stays on your device. Send it through the verified seller contact channel supplied with this portfolio. Nothing is submitted here.</p><label for="enquiry-text">Enquiry draft</label><textarea id="enquiry-text" rows="13"></textarea><div class="dialog-actions"><button class="button" data-copy-enquiry>Copy draft</button><button class="button secondary" data-save-enquiry>Save draft</button></div><p class="small" id="enquiry-feedback" role="status" aria-live="polite"></p></dialog>'
 def shell(title,description,content,body='',canonical=None,root=False):
  prefix='' if root else '../../';head='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+escape(description,quote=True)+'"><title>'+escape(title)+' — THEARCHITECT_MAX</title><link rel="stylesheet" href="'+prefix+'assets/exhibition.css?v=showroom1"><link rel="stylesheet" href="'+prefix+'assets/buyer-showroom.css?v=showroom4">'
  if canonical:head+='<link rel="canonical" href="'+canonical+'">'
  h=header.replace('../../acquisition.html','acquisition.html') if root else header
  return '<!doctype html><html lang="en"><head>'+head+'</head><body'+body+'>'+h+'<main id="main">'+content+'</main>'+footer+dialog+'<script src="'+prefix+'assets/exhibition.js?v=showroom1" defer></script><script src="/MyProjects/assets/audio-player.js?v=music3" defer></script></body></html>'
 mapping=[];cards=[];rows=[]
 for a in projects:
  ref=a['ref'];slug=a['slug'];c=cats[a['categoryId']];prices=price_record(a,pricing)['values'];folder=ROOT/'products'/slug;folder.mkdir(parents=True,exist_ok=True)
  actions='<div class="hero-actions"><button class="button" data-asset-enquiry data-ref="'+ref+'" data-title="'+escape(a['title'],quote=True)+'" data-price="'+str(a['askingReferenceEUR'])+'">Discuss this asset ↗</button><a class="button secondary" href="factsheet.pdf" download>Factsheet PDF ↓</a></div>'
  hero='<section class="product-hero"><div class="hero-copy"><p class="eyebrow">'+ref+' / INDEPENDENT IP ASSET</p><h1>'+escape(a['title'])+'</h1><p class="hero-lede">'+escape(a['summary'])+'</p>'+actions+'</div><aside class="asset-plaque"><span class="plaque-id">'+ref+'</span><p>'+escape(c['title'])+'</p><div class="plaque-alias">'+escape(a['referenceName'])+'</div><span class="stage">'+escape(a['maturity'])+'</span><div class="plaque-price"><span>SELLER ASKING REFERENCE / AS IS</span><strong>'+money(a['askingReferenceEUR'])+'</strong><small class="price-usd" data-currency="USD">≈ '+usd(a['askingReferenceEUR'],pricing)+'</small><span class="restored-plaque-label">RECREATION COST ESTIMATE</span><strong class="restored-plaque-cost">'+money(prices['replacementCostEUR'])+'</strong><small class="price-usd" data-currency="USD">≈ '+usd(prices['replacementCostEUR'],pricing)+'</small><a class="price-source-short" href="#pricing">All prices &amp; sources →</a></div></aside></section>'
  body=hero+'<nav class="page-nav" aria-label="On this page"><a href="#product">Overview</a><a href="#buyer-fit">Buyer fit</a><a href="#functions">Functions &amp; outputs</a><a href="#scope">Current scope</a><a href="#acquire">Acquisition</a><a href="#product-dossier">Product dossier</a><a href="#pricing">Prices &amp; sources</a><a href="#buyer-information">Documents</a></nav><div class="product-content">'
  content=[('product','01','Product overview','<p class="lead-copy">'+escape(a['overview'])+'</p>'),('buyer-fit','02','Potential acquirers',ul(a['potentialBuyers'])+'<p>'+escape(a['summary'])+'</p>'),('functions','03','Functions & outputs','<h3>Documented functions</h3>'+ul(a['capabilities'])+'<h3>Available output types</h3>'+ul(a['outputTypes'])),('scope','04','Current offered position','<dl class="status-grid"><div><dt>Development stage</dt><dd>'+escape(a['maturity'])+'</dd></div><div><dt>Acquisition position</dt><dd>'+escape(a['availability'])+'</dd></div></dl><p>'+escape(a['maturityNote'])+'</p><div class="boundary-box"><h3>Material scope conditions</h3>'+ul(a['materialBoundaries'])+'</div>'),('acquire','05','Acquisition perimeter','<div class="economics-grid"><div><span>Seller asking reference</span><strong>'+money(a['askingReferenceEUR'])+'</strong><small>Indicative seller reference · EUR</small></div><div><span>Offered transaction</span><strong>AS IS</strong><small>Separate written agreement</small></div></div><p class="small">The asking reference is a seller choice, not an independent market appraisal. Final rights, delivery, acceptance and consideration are agreed separately.</p><div class="scope-columns"><div><h3>Offered first-party scope</h3>'+ul(a['offeredScope'])+'</div><div><h3>Separately scoped or excluded</h3>'+ul(a['excludedScope'])+'</div></div>'+actions),('buyer-information','07','Buyer information','<p>Review the concise factsheet or the product brief. Further technical, legal and commercial diligence is handled through an agreed review process.</p><div class="buyer-info-actions"><a class="button" href="factsheet.pdf" download>Factsheet PDF ↓</a><a class="button secondary" href="product-brief.md" download>Product brief ↓</a></div><p><a class="text-link" data-project-profile href="'+a['profileUrl']+'">View full asset profile ↗</a></p>')]
  content.insert(-1,('product-dossier','06','Product edition & qualification',dossier_html(a,dossier_by_ref[ref],applications)))
  content.insert(-1,('pricing','06','Prices &amp; sources',price_html(a,pricing)))
  for id_,num,title,text in content:body+='<section id="'+id_+'" class="split-section"><div><p class="eyebrow">'+num+' / '+title.upper()+'</p><h2>'+title+'</h2></div><div>'+text+'</div></section>'
  body+='</div>'
  (folder/'index.html').write_text(shell(a['title'],a['summary'],body,body=' data-project-ref="'+ref+'" data-project-slug="'+slug+'" style="--accent:#c5a46d"',canonical=a['profileUrl']))
  brief='# '+a['title']+'\n\n'+ref+' | Reference name: '+a['referenceName']+' | '+c['title']+'\n\n'+a['summary']+'\n\n'
  sections=[('Product overview',a['overview']),('Potential acquirers','\n'.join('- '+s for s in a['potentialBuyers'])),('Documented functions','\n'.join('- '+s for s in a['capabilities'])),('Available output types','\n'.join('- '+s for s in a['outputTypes'])),('Current offered position',a['maturity']+'. '+a['maturityNote']+'\n\n'+a['availability']+'.\n\n'+'\n'.join('- '+s for s in a['materialBoundaries'])),('Acquisition reference','Seller asking reference: '+money(a['askingReferenceEUR'])+'.\n\nAcquisition of the specifically agreed first-party work product and transferable rights, AS IS. The asking reference is a seller choice, not an independent market appraisal. Final delivery, rights, acceptance, consideration and taxes require a separate written agreement.'),('Offered first-party scope','\n'.join('- '+s for s in a['offeredScope'])),('Separately scoped or excluded','\n'.join('- '+s for s in a['excludedScope'])),('Buyer information and enquiry','Asset profile: '+a['profileUrl']+'\n\nFactsheet: '+a['factsheetUrl']+'\n\nQuote '+ref+' and the project title when discussing your intended use and requested scope through the verified seller contact channel supplied with this portfolio. Detailed diligence is shared through an agreed review process.')]
  brief+=''.join('## '+title+'\n\n'+text+'\n\n' for title,text in sections)+'Buyer profiles describe potential fit; no existing customer, contract or commercial outcome is implied. Public viewing and receipt of this document do not grant rights in the underlying software.\n\n© 2026 THEARCHITECT_MAX. First-party rights reserved.\n'
  brief+='\n'+dossier_brief(a,dossier_by_ref[ref],applications)+'\n'+brief_prices(a,pricing)
  (folder/'product-brief.md').write_text(brief)
  mapping.append(dict(ref=ref,title=a['title'],slug=slug,displaySlug=slug,productPage='products/'+slug+'/index.html',url=a['displayUrl'],profileUrl=a['profileUrl'],factsheetUrl=a['factsheetUrl'],briefUrl=a['briefUrl']))
  rows.append(dict(Reference=ref,Project=a['title'],Reference_name=a['referenceName'],Application=c['title'],Potential_acquirers='; '.join(a['potentialBuyers']),Purpose=a['summary'],Maturity=a['maturity'],Seller_asking_reference_EUR=a['askingReferenceEUR'],Asset_profile=a['profileUrl'],Factsheet=a['factsheetUrl'],Product_brief=a['briefUrl']))
  rows[-1].update({f['key']:prices[f['key']] for f in pricing['fields']});rows[-1].update(price_record(a,pricing)['valuesUSD']);rows[-1]['USD_per_EUR']=pricing['displayCurrency']['rate'];rows[-1]['FX_date']=pricing['displayCurrency']['date'];rows[-1]['Calculation_validation']=HUB+'proof.html?v=calc1';rows[-1]['Milestone_conditioned_reference_EUR']=price_record(a,pricing)['futureReference'].get('milestoneConditionedEconomicReferenceEUR','');rows[-1]['Milestone_conditioned_reference_USD']=price_record(a,pricing)['futureReference'].get('milestoneConditionedEconomicReferenceUSD','');rows[-1]['Pricing_and_sources']=a['profileUrl']+'#pricing';rows[-1]['Source_URLs']='; '.join(source['url'] for source in pricing['sources'] if source['id'] in price_record(a,pricing)['sourceIds']);rows[-1]['Product_edition']=dossier_by_ref[ref]['version'];rows[-1]['Development_edition']=dossier_by_ref[ref]['developmentEdition'];rows[-1]['Handover_position']=dossier_by_ref[ref]['transferPosition'];rows[-1]['Acquisition_dossier']=a['profileUrl']+'#product-dossier';rows[-1]['Seller_conditions']='; '.join(dossier_by_ref[ref]['sellerConditions'])
  search=' '.join([ref,a['title'],a['referenceName'],a['summary'],c['title'],*a['potentialBuyers'],*a['capabilities']]).lower()
  cards.append('<article class="asset-card" data-project-ref="'+ref+'" data-name="'+escape(a['title'].lower(),quote=True)+'" data-search="'+escape(search,quote=True)+'" data-family="'+a['categoryId']+'" data-buyers="'+' '.join(a['buyerGroupIds'])+'" data-stage="'+a['maturity']+'" data-price="'+str(a['askingReferenceEUR'])+'" style="--accent:#c5a46d"><div class="card-top"><span>'+ref+'</span><span>'+escape(a['referenceName'])+'</span></div><p class="card-family">'+escape(c['title'])+'</p><h3>'+escape(a['title'])+'</h3><p class="card-description">'+escape(a['summary'])+'</p><div class="buyer-card-fit"><strong>Potential acquirers</strong><p>'+escape(' · '.join(a['potentialBuyers']))+'</p></div><div class="card-bottom"><span class="stage">'+a['maturity']+'</span><strong>'+money(a['askingReferenceEUR'])+'</strong></div><small class="price-usd" data-currency="USD">≈ '+usd(a['askingReferenceEUR'],pricing)+'</small><p class="card-cost">Recreation estimate: '+money(prices['replacementCostEUR'])+'<small class="price-usd" data-currency="USD">≈ '+usd(prices['replacementCostEUR'],pricing)+'</small></p><a class="card-link" href="products/'+slug+'/index.html">Review asset ↗</a><label class="select-asset"><input type="checkbox" class="asset-select" value="'+ref+'" data-title="'+escape(a['title'],quote=True)+'" data-price="'+str(a['askingReferenceEUR'])+'"> Include in enquiry</label></article>')
 intro='<section class="home-hero"><div><p class="eyebrow">INDEPENDENT SOFTWARE IP</p><h1>Find the work product.<br>Define your acquisition.</h1><p class="hero-lede">Explore the collection by application and potential buyer. Review each asset’s purpose, documented functions, offered scope and available information before discussing terms.</p><div class="hero-actions"><a class="button" href="#collection">Explore the collection ↗</a><a class="button secondary" href="'+HUB+'buyers.html">Browse by buyer fit</a></div></div><aside class="hero-note"><p class="eyebrow">108 INDEPENDENT ASSETS</p><p>Individual identity.<br>Defined work product.<br>Separate written terms.</p><a class="text-link" href="'+HUB+'acquisition.html">How acquisition works ↗</a></aside></section>'
 filters='<section class="collection" id="collection"><div class="collection-heading"><div><p class="eyebrow">THE IP COLLECTION</p><h2>Application. Buyer fit. Current scope.</h2></div><p><span id="result-count">108</span> assets</p></div><div class="filter-layout"><aside class="family-panel"><h3>Application area</h3><button class="active" data-family-filter="all" aria-pressed="true">All applications</button>'+''.join('<button data-family-filter="'+c['id']+'" aria-pressed="false">'+escape(c['title'])+'</button>' for c in d['categories'])+'</aside><div><div class="toolbar buyer-toolbar"><label>Search<input id="asset-search" type="search" placeholder="Project, purpose or acquirer…"></label><label>Buyer type<select id="buyer-filter"><option value="all">All potential acquirers</option>'+''.join('<option value="'+g['id']+'">'+escape(g['title'])+'</option>' for g in d['buyerGroups'])+'</select></label><label>Stage<select id="stage-filter"><option value="all">All stages</option>'+''.join('<option>'+stage+'</option>' for stage in ['Developed software','Prototype','Research software'])+'</select></label><label>Sort<select id="sort-order"><option value="name">Project A–Z</option><option value="price-asc">Asking reference low–high</option><option value="price-desc">Asking reference high–low</option></select></label></div><div id="selection-bar" class="selection-bar" hidden><span><b id="selection-count">0</b> assets selected</span><button class="button compact" data-selection-enquiry>Prepare enquiry</button><button class="text-link" data-clear-selection>Clear selection</button></div><p id="empty-state" hidden>No assets match these criteria.</p><div class="asset-grid" id="asset-grid">'+''.join(cards)+'</div><noscript><p>The complete collection remains visible. Interactive filters and local draft preparation require JavaScript.</p></noscript></div></div></section>'
 (ROOT/'index.html').write_text(shell('Software IP asset exhibition','Browse independent software assets by application and potential buyer.',intro+filters,root=True,canonical=HUB+'portfolio.html'))
 save=lambda path,value:path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
 save(ROOT/'project-map.json',dict(schema='public-project-map-1',projectCount=108,projects=mapping))
 with (ROOT/'catalogue.csv').open('w',newline='',encoding='utf-8-sig') as file:
  w=csv.DictWriter(file,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
 information={
 'acquisition.html':('Acquisition','<section><h2>Review the asset. Agree the scope.</h2><p>Read the project profile and information documents. Discuss the intended use, delivery edition, rights, diligence and acceptance requirements. Final consideration and handover require a definitive written agreement.</p></section><section><h2>Prepare a clear enquiry</h2><p>Quote the asset title and TA-IP reference and describe your organisation, intended application and requested scope. Send your draft through the verified seller contact channel supplied with the portfolio.</p><a class="button" href="'+HUB+'acquisition.html#enquiry">Prepare an acquisition enquiry ↗</a></section>'),
 'methodology.html':('Commercial terms','<section><h2>Seller asking references</h2><p>Each asset has an individual indicative asking reference in EUR. It is a seller choice for a specifically defined AS IS work product, not an independent market appraisal or a completed sale. Final consideration and taxes are agreed separately.</p></section><section><h2>Scope before transfer</h2><p>Agree the delivery edition, included first-party rights, third-party treatment and recipient acceptance. Production operation, future development, support, customer content and operating businesses are not automatically included.</p><a class="button" href="'+HUB+'policy.html">Read terms and disclosure ↗</a></section>'),
 'sources.html':('Buyer information','<section><h2>Product information for initial review</h2><p>Each asset has a concise PDF factsheet, an editable product brief and a buyer profile. They describe the purpose, potential acquirers, functions, output types, current scope and indicative seller asking reference.</p></section><section><h2>Detailed diligence by agreement</h2><p>Discuss the source and delivery package, rights documentation, relevant evaluation material and handover conditions through an agreed review process and appropriate confidentiality.</p><p>Potential buyer descriptions indicate fit, not existing customers, contracts or guaranteed outcomes.</p><a class="button" href="catalogue.csv" download>Download the buyer catalogue ↓</a></section>')}
 information['methodology.html']=('Price method & assumptions','<section><h2>Recreation cost, asking prices and model scenarios</h2><p>'+escape(pricing['statement'])+'</p><p>'+escape(pricing['methodology']['lowestCostPolicy'])+'</p><a class="button" href="'+HUB+'valuation.html#methodology">Complete model, rate assumptions and arithmetic ↗</a></section>')
 information['sources.html']=('Prices & source register','<section><h2>Contextual sources</h2><p>Project prices are seller choices and model outputs. Sources inform the method, contractor rates and currency; they do not provide or endorse individual asset valuations.</p>'+''.join('<article><h3><a href="'+escape(source['url'],quote=True)+'" target="_blank" rel="noopener">'+escape(source['publisher']+' - '+source['title'])+'</a></h3><p>'+escape(source['finding'])+'</p><p>'+escape(source['application'])+'</p></article>' for source in pricing['sources'])+'<a class="button" href="catalogue.csv" download>Download all prices & sources CSV ↓</a></section>')
 information['methodology.html']=(information['methodology.html'][0],information['methodology.html'][1]+'<section><h2>Reproduce the calculation</h2><p>Four scenario outputs per asset are recalculated from the disclosed factors. The weighted blend uses 25% recreation cost, 20% marketability, 20% monetisation and 35% strategic reference. USD amounts are EUR multiplied by '+str(pricing['displayCurrency']['rate'])+', rounded half-up to whole USD; ECB date '+pricing['displayCurrency']['date']+'.</p><a class="button" href="'+HUB+'proof.html?v=calc1">Run calculation validation ↗</a></section>')
 for name,(title,text) in information.items():(ROOT/name).write_text(shell(title,title+' for prospective acquirers.','<div class="information-page"><p class="eyebrow">IP ASSET ACQUISITION</p><h1>'+title+'</h1>'+text+'</div>',root=True))
 # Maintain the six established route aliases without exposing earlier content.
 for a in json.loads((ROOT/'assets/route-aliases.json').read_text())['aliases']:
  folder=ROOT/'products'/a['legacySlug'];folder.mkdir(exist_ok=True);target=HUB+'displays/products/'+a['slug']+'/'
  (folder/'index.html').write_text(redirect(target,a['ref']))
  for name in ['factsheet.pdf','product-brief.md']:
   if (ROOT/'products'/a['slug']/name).is_file():shutil.copy2(ROOT/'products'/a['slug']/name,folder/name)
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+escape(a['profileUrl'])+'</loc></url>' for a in projects)+'</urlset>\n')
 (ROOT/'PRESENTATION_NOTICE.txt').write_text('THEARCHITECT_MAX — SOFTWARE IP ASSET EXHIBITION\n\nPublic buyer information only. Viewing or downloading these materials does not grant rights in the underlying software. Acquisition requires specifically agreed first-party rights, work product, delivery and written terms. Third-party materials retain their own rights.\n')
 print('Built 108 buyer displays, product briefs, collection cards and public catalogue records.')

def redirect(target,ref=''):
 code='const u=new URL('+json.dumps(target)+',location.href);u.search=location.search;u.hash=location.hash;location.replace(u.href);'
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="canonical" href="'+target+'"><title>IP asset presentation</title></head><body data-legacy-project-ref="'+ref+'"><p><a href="'+target+'">Continue to the asset presentation</a></p><script>'+code+'</script></body></html>'

if __name__=='__main__':main()
